import{_ as a,o as n,c as t,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"spec — People avatars everywhere (web)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/people-avatars/spec.md","filePath":"feature/people-avatars/spec.md"}'),h={name:"feature/people-avatars/spec.md"};function o(r,e,c,s,l,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="spec-—-people-avatars-everywhere-web" tabindex="-1">spec — People avatars everywhere (web) <a class="header-anchor" href="#spec-—-people-avatars-everywhere-web" aria-label="Permalink to &quot;spec — People avatars everywhere (web)&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Mọi chỗ trên web hiển thị một <strong>người</strong> (assignee, reporter, tác giả comment, người gửi chat, thành viên trong picker/danh sách) dùng ảnh avatar thay cho 2 chữ viết tắt. Đối tác (partner: báo, TV, banner) dùng hình khối minh họa. Mục tiêu: giao diện sinh động, đồng nhất.</p><h2 id="user-story" tabindex="-1">User Story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User Story&quot;">​</a></h2><p>Là Owner/Manager/Creator/Client, tôi nhìn timeline, danh sách task, chat, picker thành viên và nhận ra người qua ảnh của họ.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ol><li>Người có <code>avatarUrl</code> → hiển thị ảnh đã upload.</li><li>Người chưa có ảnh, hoặc ảnh lỗi tải → ảnh minh họa DiceBear <code>notionists</code> sinh offline theo tên (cùng tên = cùng hình ở mọi màn hình).</li><li>Đối tác → DiceBear <code>shapes</code> theo tên đối tác.</li><li>API bổ sung avatar ở các payload còn thiếu: thành viên workspace, thành viên chat directory, tác giả comment task và danh sách mention comment.</li><li>Không gọi dịch vụ ngoài; không lộ dữ liệu user ra bên thứ ba.</li><li><strong>i18n:</strong> không có text hiển thị mới; <code>alt</code> = tên người (dữ liệu, không phải chuỗi UI). Không đổi <code>vi.json</code>/<code>en.json</code>.</li><li><strong>Light/Dark:</strong> ảnh minh họa có nền pastel cố định trong chính ảnh nên đọc được ở cả hai theme; khung ảnh dùng token <code>bg-muted</code>. Không thêm token màu.</li></ol><h2 id="ui-states" tabindex="-1">UI States <a class="header-anchor" href="#ui-states" aria-label="Permalink to &quot;UI States&quot;">​</a></h2><ul><li>Có ảnh → ảnh. Không ảnh → minh họa. Ảnh lỗi → minh họa. Chưa gán người → giữ icon &quot;chưa gán&quot; (nét đứt) như hiện tại.</li></ul><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><p>Tên rỗng → seed <code>?</code>. Tên trùng nhau → cùng minh họa (chấp nhận). Đổi tên → minh họa đổi (chấp nhận, ghi chú ceiling).</p><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><p>tsc + lint sạch, test backend xanh, kiểm tra trên trình duyệt các màn: task list/board/timeline, chat, members, collaborators.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><p>Logo workspace / client profile / agency (là thương hiệu, đã có logo uploader). Mobile app. Mockup mạng xã hội trong editor. Landing page.</p>',15)])])}const u=a(h,[["render",o]]);export{g as __pageData,u as default};
